const outputFiles = require('./common/outputFiles.js');
const gitStaging = require('./common/gitStaging.js');
const feedbackLoop = require('./common/feedbackLoop.js');

function cleanCliOutput(output) {
    return (output || '').split('\n').filter(function(l) {
        return l.trim() &&
               l.indexOf('Script started') === -1 &&
               l.indexOf('Script done') === -1 &&
               l.indexOf('COMMAND=') === -1 &&
               l.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('').trim();
}

function readJson(path) {
    try {
        const raw = outputFiles.readOutputFile(path, {});
        return (raw && raw.trim()) ? JSON.parse(raw) : null;
    } catch (e) {
        return null;
    }
}

function hasCodeGraphUsage() {
    try {
        const raw = file_read({ path: '.dmtools/codegraph-usage.log' });
        return !!(raw && raw.trim());
    } catch (e) {
        return false;
    }
}

/**
 * True when outputs/response.md exists with content (shared by the initial
 * tree check and the gh-775 post-resume re-check so both use one read shape).
 */
function readHasResponseMd(ticketKey) {
    try {
        const r = outputFiles.readOutputFile('response.md', { ticketKey: ticketKey });
        return !!(r && r.trim());
    } catch (e) {
        return false;
    }
}

function removeLabels(ticketKey, params) {
    const wipLabel = params.metadata && params.metadata.contextId
        ? params.metadata.contextId + '_wip' : null;
    if (wipLabel) {
        try { jira_remove_label({ key: ticketKey, label: wipLabel }); } catch (e) {}
    }

    const customParams = params.jobParams && params.jobParams.customParams;
    const removeLabel = customParams && customParams.removeLabel;
    if (removeLabel) {
        try {
            jira_remove_label({ key: ticketKey, label: removeLabel });
            console.log('✅ Removed SM label:', removeLabel);
        } catch (e) {}
    }
}

function action(params) {
    try {
        const actualParams = params.ticket ? params : (params.jobParams || params);
        const ticketKey = actualParams.ticket.key;
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var jiraConfig = config.jira;
        var scm = configLoader.createScm(config);
