            if (!hasCodeGraphUsage()) {
                console.warn('outputs/blocked.json rejected — no CodeGraph usage was recorded');
                try {
                    jira_post_comment({
                        key: ticketKey,
                        comment: commentMarkup.forTicket(ticketKey).h(3, '⚠️ Blocked Claim Needs CodeGraph Verification') + '\n\n' +
